package com.yazaki.printingservice.application;
import static org.junit.jupiter.api.Assertions.*; import java.net.*; import java.net.http.*; import java.util.UUID; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.context.annotation.Import; import org.springframework.test.context.ActiveProfiles;
import com.yazaki.printingservice.TestcontainersConfiguration; import com.yazaki.printingservice.api.dto.*; import com.yazaki.printingservice.api.error.ConflictException; import com.yazaki.printingservice.domain.model.*; import com.yazaki.printingservice.domain.repository.*;
@ActiveProfiles("test") @Import(TestcontainersConfiguration.class) @SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties={"printing.queue.enabled=true","printing.queue.poll-delay=3600000","printing.adapters.label-mode=SUCCESS"})
class PrintingWorkflowIntegrationTest {
 @org.springframework.boot.test.web.server.LocalServerPort int port; @Autowired PrinterService printers; @Autowired PrintJobService jobs; @Autowired PrintQueueWorker worker; @Autowired PrintAttemptRepository attempts; @Autowired DashboardService dashboard; UUID printerId;
 @BeforeEach void setup(){printerId=printers.create(new PrinterDtos.Upsert("TEST-"+UUID.randomUUID(),"Fictitious test printer",PrinterType.LABEL,"Test area",null,PrinterStatus.ONLINE,null,true)).id();}
 @Test void createsIdempotentlyAndRejectsChangedContent(){var input=new PrintJobDtos.Create("TEST_SYSTEM","ext-"+UUID.randomUUID(),"ORDER-TEST",PrinterType.LABEL,"{\"demo\":true}",printerId,2);var first=jobs.create(input);var second=jobs.create(input);assertTrue(first.created());assertFalse(second.created());assertEquals(first.job().id(),second.job().id());var changed=new PrintJobDtos.Create(input.sourceSystem(),input.externalRequestId(),input.orderId(),input.printType(),"{\"demo\":false}",printerId,2);assertThrows(ConflictException.class,()->jobs.create(changed));}
 @Test void workerReservesRoutesAndRecordsAttempt(){var id=jobs.create(new PrintJobDtos.Create("TEST_SYSTEM","queue-"+UUID.randomUUID(),null,PrinterType.LABEL,"{}",printerId,2)).job().id();worker.poll();assertEquals(PrintJobStatus.SUBMITTED,jobs.get(id).status());assertEquals(1,attempts.findByPrintJobIdOrderByAttemptNumber(id).size());assertTrue(dashboard.summary().submitted()>=1);}
 @Test void reprintCreatesLinkedNewJobAndCancellationIsRecorded(){var id=jobs.create(new PrintJobDtos.Create("TEST_SYSTEM","reprint-"+UUID.randomUUID(),null,PrinterType.LABEL,"{}",printerId,2)).job().id();var reprint=jobs.reprint(id);assertNotEquals(id,reprint.id());assertEquals(id,reprint.reprintOfJobId());assertEquals(PrintJobStatus.CANCELLED,jobs.cancel(reprint.id()).status());assertFalse(jobs.events(reprint.id()).isEmpty());}
 @Test void dashboardEndpointRespondsAndInvalidJobReturnsStructured400() throws Exception {var client=HttpClient.newHttpClient();var summary=client.send(HttpRequest.newBuilder(URI.create("http://localhost:"+port+"/api/v1/dashboard/summary")).GET().build(),HttpResponse.BodyHandlers.ofString());assertEquals(200,summary.statusCode());assertTrue(summary.body().contains("totalJobs"));var invalid=client.send(HttpRequest.newBuilder(URI.create("http://localhost:"+port+"/api/v1/print-jobs")).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString("{}")).build(),HttpResponse.BodyHandlers.ofString());assertEquals(400,invalid.statusCode());assertTrue(invalid.body().contains("VALIDATION_ERROR"));}
}
